// Only JSON + a trusted media reference in v1. Never accept arbitrary remote URLs.
const web = $input.first().json;
const body = web.body && typeof web.body === 'object' && !Array.isArray(web.body) ? web.body : {};
const errors = [];
const report_id = typeof body.report_id === 'string' ? body.report_id.trim() : '';
const description = typeof body.description === 'string' ? body.description.trim() : '';
const media_ref = typeof body.media_ref === 'string' ? body.media_ref.trim() : '';
if (!/^[A-Za-z0-9_-]{3,64}$/.test(report_id)) errors.push('INVALID_REPORT_ID');
if (description.length < 5 || description.length > 3000) errors.push('INVALID_DESCRIPTION');
if (!media_ref) errors.push('MISSING_MEDIA_REF');
else if (media_ref.length > 512 || media_ref.includes('..') || !/^(mock:\/\/[a-z0-9_-]+|uploads\/[A-Za-z0-9_./-]+)$/.test(media_ref)) errors.push('UNSAFE_MEDIA_REF');
let location = null;
if (body.location !== undefined && body.location !== null) {
  const loc = body.location;
  if (typeof loc !== 'object' || Array.isArray(loc)) errors.push('INVALID_LOCATION');
  else {
    const lat = loc.latitude === undefined || loc.latitude === null ? null : loc.latitude;
    const lon = loc.longitude === undefined || loc.longitude === null ? null : loc.longitude;
    const address = typeof loc.address === 'string' ? loc.address.trim() : null;
    if ((lat !== null && (typeof lat !== 'number' || !Number.isFinite(lat) || Math.abs(lat) > 90)) ||
        (lon !== null && (typeof lon !== 'number' || !Number.isFinite(lon) || Math.abs(lon) > 180)) ||
        (address !== null && address.length > 300)) errors.push('INVALID_LOCATION');
    else location = {latitude:lat,longitude:lon,address:address || null};
  }
}
const decision = errors.length ? 'REJECT' : 'PASS';
return [{json:{
  report_id: report_id || null,
  // For the first prototype, this is set by the workflow OWNER, not by the caller.
  demo_mode:true,
  input: {description,media_ref,location},
  decision,errors, review_reasons:[],
  versions:{orchestrator:'member1-v4'},
  started_at: new Date().toISOString(),
  trace:[{at:new Date().toISOString(),stage:'INPUT_CHECK',decision,reason_codes:[...errors]}]
}}];

const x = $input.first().json;
const r = x.intake;
const problems=[];
if (!r || typeof r!=='object') problems.push('INTAKE_ENDPOINT_FAILED_OR_INVALID');
else {
  if (r.report_id !== x.report_id) problems.push('INTAKE_REPORT_ID_MISMATCH');
  if (r.media_ref !== x.input.media_ref) problems.push('INTAKE_MEDIA_REF_MISMATCH');
  if (r.input_type !== 'IMAGE_TEXT' || typeof r.cleaned_description !== 'string' || !r.cleaned_description.trim()) problems.push('INTAKE_MISSING_FIELDS');
  if (!Array.isArray(r.errors)) problems.push('INTAKE_ERRORS_INVALID');
  const fixture = x.demo_mode===true && x.input.media_ref.startsWith('mock://') &&
    r.is_mock===true && r.media_validation==='MOCK_FIXTURE' && r.validity==='MOCK_VALID' &&
    Array.isArray(r.errors) && r.errors.length===0;
  const real = x.input.media_ref.startsWith('uploads/') && r.is_mock!==true &&
    r.media_validation==='VERIFIED' && r.validity==='VALID' &&
    r.privacy_status==='ANONYMIZED' && r.image_anonymized===true &&
    typeof r.anonymized_media_ref==='string' && /^safe\/[A-Za-z0-9_./-]+$/.test(r.anonymized_media_ref) &&
    !r.anonymized_media_ref.includes('..') &&
    Array.isArray(r.errors) && r.errors.length===0;
  if (!fixture && !real) problems.push('INTAKE_MEDIA_OR_PRIVACY_NOT_VERIFIED');
}
x.decision=problems.length?'REVIEW':'PASS';
x.review_reasons.push(...problems);
x.trace.push({at:new Date().toISOString(),stage:'GATE_1_INTAKE',decision:x.decision,reason_codes:problems});
return [{json:x}];

const x = $input.first().json;
const v = x.vision;
const problems = [];
const accepted = ['ROAD_DAMAGE','STREET_LIGHTING','WASTE','WATER_LEAK'];
if (!v || typeof v !== 'object') {
  problems.push('VISION_ENDPOINT_FAILED_OR_INVALID');
} else {
  if (v.report_id !== x.report_id) problems.push('VISION_REPORT_ID_MISMATCH');
  if (!accepted.includes(v.category)) problems.push('UNKNOWN_CATEGORY');
  if (!['LOW','MEDIUM','HIGH'].includes(v.severity)) problems.push('UNKNOWN_SEVERITY');
  if (v.text_image_consistent !== true) problems.push('IMAGE_TEXT_MISMATCH_OR_UNCLEAR');
  if (v.uncertainty !== false) problems.push('VISION_UNCERTAIN');
  if (!Array.isArray(v.evidence) || v.evidence.length === 0 ||
      !v.evidence.every(e => typeof e === 'string' && e.trim().length > 0))
    problems.push('VISION_MISSING_EVIDENCE');
  if (typeof v.description !== 'string' || !v.description.trim()) problems.push('VISION_MISSING_DESCRIPTION');
  if (typeof v.agent_version !== 'string' || !v.agent_version.trim()) problems.push('VISION_VERSION_MISSING');
  if (v.confidence !== null && v.confidence !== undefined &&
      (typeof v.confidence !== 'number' || !Number.isFinite(v.confidence) || v.confidence < 0 || v.confidence > 1))
    problems.push('VISION_INVALID_CONFIDENCE');
  const fixture = x.input.media_ref.startsWith('mock://');
  if (fixture && v.is_mock !== true) problems.push('VISION_FIXTURE_PROVENANCE_INVALID');
  if (!fixture && v.is_mock === true) problems.push('VISION_MOCK_CANNOT_VALIDATE_REAL_MEDIA');
  // No confidence threshold is treated as correctness evidence; human review handles uncertainty.
}
x.decision = problems.length ? 'REVIEW' : 'PASS';
x.review_reasons.push(...problems);
x.trace.push({at:new Date().toISOString(),stage:'GATE_2_VISION',decision:x.decision,reason_codes:problems});
return [{json:x}];

// Rules control the department: no LLM is permitted to choose it.
const x=$input.first().json;
const departments={
  ROAD_DAMAGE:'ROADS_DEPARTMENT',
  STREET_LIGHTING:'PUBLIC_LIGHTING_DEPARTMENT',
  WASTE:'SANITATION_DEPARTMENT',
  WATER_LEAK:'WATER_SERVICES_DEPARTMENT'
};
x.department=departments[x.vision.category]||null;
if(!x.department){x.decision='REVIEW';x.review_reasons.push('NO_DEPARTMENT_RULE');}
x.trace.push({at:new Date().toISOString(),stage:'DEPARTMENT_ROUTING',decision:x.decision,reason_codes:x.department?[]:['NO_DEPARTMENT_RULE']});
return [{json:x}];

const x = $input.first().json;
const k = x.knowledge;
const issues = [];
if (!k || typeof k !== 'object' || Array.isArray(k)) {
  issues.push('KNOWLEDGE_ENDPOINT_FAILED_OR_INVALID');
} else {
  if (k.report_id !== x.report_id) issues.push('KNOWLEDGE_REPORT_ID_MISMATCH');
  if (k.category !== x.vision.category) issues.push('KNOWLEDGE_CATEGORY_MISMATCH');
  if (k.department !== x.department) issues.push('KNOWLEDGE_DEPARTMENT_MISMATCH');
  if (typeof k.procedure !== 'string' || !k.procedure.trim()) issues.push('MISSING_PROCEDURE');
  if (typeof k.agent_version !== 'string' || !k.agent_version.trim()) issues.push('KNOWLEDGE_VERSION_MISSING');
  if (!Array.isArray(k.sources) || k.sources.length === 0) {
    issues.push('MISSING_SOURCE');
  } else {
    for (const s of k.sources) {
      if (!s || typeof s !== 'object' || Array.isArray(s) ||
          typeof s.document_title !== 'string' || !s.document_title.trim() ||
          typeof s.chunk_id !== 'string' || !s.chunk_id.trim()) {
        issues.push('INVALID_SOURCE_METADATA');break;
      }
      if (s.search_score !== null && s.search_score !== undefined &&
          (typeof s.search_score !== 'number' || !Number.isFinite(s.search_score) || s.search_score < 0 || s.search_score > 1)) {
        issues.push('INVALID_SEARCH_SCORE');break;
      }
      if (s.source_url !== null && s.source_url !== undefined &&
          (typeof s.source_url !== 'string' || !/^https:\/\//.test(s.source_url))) {
        issues.push('INVALID_SOURCE_URL');break;
      }
    }
  }
  if (x.demo_mode === true) {
    // Local test fixtures only; never trust model-supplied official-policy claims here.
    if (k.is_mock !== true || !Array.isArray(k.sources) ||
        !k.sources.every(s => s && s.is_mock === true && s.is_official === false && s.source_url === null)) {
      issues.push('INVALID_DEMO_SOURCE');
    }
    if (k.deadline !== null) issues.push('DEMO_DEADLINE_MUST_BE_NULL');
  } else {
    // Real mode requires a separate allowlist and actual source verification.
    issues.push('OFFICIAL_SOURCE_VERIFICATION_NOT_IMPLEMENTED');
  }
}
x.decision=issues.length?'REVIEW':'PASS';
x.review_reasons.push(...issues);
x.trace.push({at:new Date().toISOString(),stage:'GATE_3_KNOWLEDGE',decision:x.decision,reason_codes:issues});
return [{json:x}];

const x=$input.first().json;
x.ticket={
  ticket_id:'DEMO-TKT-'+x.report_id,
  report_id:x.report_id,status:'TICKET_CREATED',
  category:x.vision.category,severity:x.vision.severity,
  priority:x.vision.severity==='HIGH'?'HIGH':(x.vision.severity==='LOW'?'LOW':'NORMAL'),
  department:x.department,
  location:x.intake.location,
  anonymized_media_ref:null, // face blurring NOT implemented here
  procedure:x.knowledge.procedure,
  sources:x.knowledge.sources,
  deadline:x.knowledge.deadline,
  persisted:false,storage_status:'MOCK_ONLY',is_mock:true
};
x.trace.push({at:new Date().toISOString(),stage:'TICKET_CREATION',decision:'PASS',reason_codes:['DEMO_TICKET_NOT_SAVED']});
return [{json:x}];

const x=$input.first().json;
const decision=['PASS','REVIEW','REJECT'].includes(x.decision)?x.decision:'REVIEW';
const http_status=decision==='REJECT'?422:(decision==='REVIEW'?202:200);
return [{json:{
  report_id:x.report_id||null,decision,
  ticket:x.ticket||null,
  review_reasons:x.review_reasons||[],errors:x.errors||[],
  // Never conflate mock outputs with real analysis or database persistence.
  demo_mode:!!x.demo_mode,agents_are_mock:true,
  notice:'Demo only: Intake/Vision/Knowledge results are fixture-based; no actual image inference, verified municipal procedure or saved ticket.',
  versions:x.versions||{},trace:x.trace||[],audit:x.audit||null,http_status
}}];

// Restore original workflow state after HTTP Request replaces its incoming JSON.
// This project handles one report per webhook execution.
const x = $('Input Check').first().json;
const received = $input.first().json;
const isResponse = received && typeof received==='object' && !Array.isArray(received) && !received.error &&
  typeof received.report_id==='string' && typeof received.cleaned_description==='string';
if (isResponse) {
  x.intake=received;
  x.versions.intake=typeof received.agent_version==='string' ? received.agent_version : 'unknown';
  x.trace.push({at:new Date().toISOString(),stage:'INTAKE',decision:received.is_mock===true?'MOCK':'RECEIVED',reason_codes:[]});
} else {
  x.intake=null;
  x.versions.intake='unavailable';
  x.trace.push({at:new Date().toISOString(),stage:'INTAKE',decision:'REVIEW',reason_codes:['INTAKE_ENDPOINT_FAILED_OR_INVALID']});
}
return [{json:x}];

// n8n HTTP Request replaces item JSON. Restore only this execution's report state.
// The workflow handles one report per webhook execution.
const x = $('Gate 1 - Intake').first().json;
const r = $input.first().json;
const validObject = r && typeof r === 'object' && !Array.isArray(r) && !r.error &&
  typeof r.report_id === 'string' && typeof r.category === 'string';
if (validObject) {
  x.vision = r;
  x.versions.vision = typeof r.agent_version === 'string' ? r.agent_version : 'unknown';
  x.trace.push({at:new Date().toISOString(),stage:'VISION_HTTP',decision:r.is_mock === true ? 'MOCK' : 'RECEIVED',reason_codes:[]});
} else {
  x.vision = null;
  x.versions.vision = 'unavailable';
  x.trace.push({at:new Date().toISOString(),stage:'VISION_HTTP',decision:'REVIEW',reason_codes:['VISION_ENDPOINT_FAILED_OR_INVALID']});
}
return [{json:x}];

// A small metadata-only audit for the demo. This is not persistent database logging.
const x=$input.first().json;
const safeReasons = arr => Array.isArray(arr) ? arr.filter(s=>typeof s==='string').slice(0,20) : [];
const stages = Array.isArray(x.trace) ? x.trace.map(e=>({
  at:typeof e.at==='string'?e.at:null,
  stage:typeof e.stage==='string'?e.stage:'UNKNOWN',
  decision:typeof e.decision==='string'?e.decision:'UNKNOWN',
  reason_codes:safeReasons(e.reason_codes)
})) : [];
x.audit={
  report_id:x.report_id || null,
  decided_at:new Date().toISOString(),
  outcome:x.decision,
  stages,
  agent_versions:x.versions || {},
  storage:'N8N_EXECUTION_DATA_ONLY_NOT_A_TICKET_DB'
};
return [{json:x}];

// HTTP responses replace the incoming item. Restore only the current execution state.
const x = $('Department Rules').first().json;
const r = $input.first().json;
const usable = r && typeof r === 'object' && !Array.isArray(r) && !r.error &&
    typeof r.report_id === 'string' && typeof r.procedure === 'string' && Array.isArray(r.sources);
if (usable) {
  x.knowledge = r;
  x.versions.knowledge = typeof r.agent_version === 'string' && r.agent_version.trim() ? r.agent_version : 'unknown';
  x.trace.push({at:new Date().toISOString(),stage:'KNOWLEDGE_HTTP',decision:r.is_mock === true ? 'MOCK' : 'RECEIVED',reason_codes:[]});
} else {
  x.knowledge = null;
  x.versions.knowledge = 'unavailable';
  x.trace.push({at:new Date().toISOString(),stage:'KNOWLEDGE_HTTP',decision:'REVIEW',reason_codes:['KNOWLEDGE_ENDPOINT_FAILED_OR_INVALID']});
}
return [{json:x}];
